//! 2-D Lattice Flower Constellations — one integer-lattice generator that unifies Walker and Flower
//! (Avendaño, Davis & Mortari, *The 2-D lattice theory of Flower Constellations*, Celestial
//! Mechanics and Dynamical Astronomy, 2013).
//!
//! The right-ascension/mean-anomaly pairs of the satellites are placed on a lattice of the `(Ω, M)`
//! torus generated by an integer configuration. With `No` right-ascension slots, `Nso` satellites
//! per slot and a configuration number `Nc`, satellite `(i, j)` sits at
//!
//! ```text
//! Ω_ij = Ω_0 + 2π·i/No,        M_ij = 2π·( Nc·i/(No·Nso) + j/Nso ),
//! ```
//!
//! for `i = 0…No−1`, `j = 0…Nso−1` (`No·Nso` satellites, slot-major). Every satellite shares one
//! orbit shape `(a, e, i, ω)`.
//!
//! This `Nc` has the opposite sign to the paper's. Avendaño et al. define the lattice as the
//! solutions of `[No 0; Nc′ Nso]·[ΔΩ; ΔM] = 2π·[i; j]` (restated in Casanova, Avendaño & Mortari,
//! IEEE Trans. AES 50(2), 2014, p. 1348, eqs. 3–4), i.e. `M_ij = 2π·(j/Nso − Nc′·i/(No·Nso))`, so a
//! configuration taken from the literature is `Nc = −Nc′ mod No` here. Derived in
//! `derivations/lattice_flower.mac`; `derivations/lattice_flower.g` (GAP) checks the point set
//! against the paper's system; the gate is
//! `the_emitted_satellites_solve_the_hermite_normal_form_system` below.
//!
//! This subsumes the other families. A circular lattice (`e = 0`, `ω = 0`) with
//! `(No, Nso, Nc) = (P, S, F)` is a Walker-Delta `i: T/P/F`, satellite for satellite (`M ≡ ν`); the
//! `Nso = 1` case on a repeating orbit is a Flower (nodes tiling the RAAN circle, `Nc` setting the
//! along-track phasing); and the intermediate elliptical lattices (`Nso > 1`, `e > 0`) are the
//! *necklace* configurations neither family expresses alone.

use spacelab_core::Angle;
use spacelab_elements::KeplerianElements;

const TAU: f64 = core::f64::consts::TAU;

/// A 2-D Lattice Flower Constellation: `orbits · sats_per_orbit` satellites sharing one orbit shape,
/// placed on the `(Ω, M)` lattice fixed by the configuration number.
#[derive(Clone, Copy, Debug)]
pub struct LatticeFlower {
    /// `No` — number of right-ascension slots (distinct RAAN values).
    pub orbits: u32,
    /// `Nso` — satellites per slot.
    pub sats_per_orbit: u32,
    /// `Nc` — configuration number, used mod `orbits`; the inter-slot along-track shift. The
    /// literature's `Nc′` (Avendaño et al. 2013) is `−Nc mod No`.
    pub config: u32,
    /// Common semi-major axis, metres.
    pub semi_major_axis: f64,
    /// Common eccentricity `e`.
    pub eccentricity: f64,
    /// Common inclination `i`.
    pub inclination: Angle,
    /// Common argument of periapsis `ω`.
    pub arg_periapsis: Angle,
    /// Base right ascension `Ω_0` of slot 0.
    pub raan0: Angle,
    /// Gravitational parameter, m³/s².
    pub mu: f64,
}

impl LatticeFlower {
    /// Total number of satellites `No · Nso`.
    #[must_use]
    pub const fn total(&self) -> u32 {
        self.orbits * self.sats_per_orbit
    }

    /// Emit the lattice's elements, slot-major (all of slot 0, then slot 1, …). Satellite `(i, j)`
    /// sits at `Ω_0 + 2π·i/No` with mean anomaly `2π·(Nc·i/(No·Nso) + j/Nso)`, converted to a true
    /// anomaly via [`KeplerianElements::at_mean_anomaly`]. A degenerate lattice (`orbits` or
    /// `sats_per_orbit` zero) emits nothing.
    pub fn generate<E: FnMut(KeplerianElements)>(&self, mut emit: E) {
        let (no, nso) = (self.orbits, self.sats_per_orbit);
        if no == 0 || nso == 0 {
            return;
        }
        let nc = f64::from(self.config % no);
        let raan0 = self.raan0.radians();
        let raan_step = TAU / f64::from(no);
        let inv_slot = 1.0 / f64::from(nso);
        let denom = f64::from(no) * f64::from(nso);
        for i in 0..no {
            let raan = raan0 + f64::from(i) * raan_step;
            let slot_shift = nc * f64::from(i) / denom; // Nc·i/(No·Nso)
            for j in 0..nso {
                let mean = TAU * libm::fmod(slot_shift + f64::from(j) * inv_slot, 1.0);
                let base = KeplerianElements {
                    semi_major_axis: self.semi_major_axis,
                    eccentricity: self.eccentricity,
                    inclination: self.inclination,
                    raan: Angle::from_radians(raan),
                    arg_periapsis: self.arg_periapsis,
                    true_anomaly: Angle::from_radians(0.0),
                    mu: self.mu,
                };
                emit(base.at_mean_anomaly(Angle::from_radians(mean)));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    #![allow(
        clippy::float_cmp,
        clippy::unwrap_used,
        clippy::cast_possible_truncation
    )]
    use super::*;
    use crate::{Walker, WalkerPattern};

    const MU: f64 = 3.986_004_418e14;
    const RE: f64 = 6_378_137.0;

    fn collect_lattice(l: &LatticeFlower) -> Vec<KeplerianElements> {
        let mut v = Vec::new();
        l.generate(|e| v.push(e));
        v
    }

    #[test]
    fn count_is_orbits_times_sats_per_orbit() {
        let l = LatticeFlower {
            orbits: 6,
            sats_per_orbit: 9,
            config: 2,
            semi_major_axis: RE + 1_000e3,
            eccentricity: 0.0,
            inclination: Angle::from_radians(1.1),
            arg_periapsis: Angle::from_radians(0.0),
            raan0: Angle::from_radians(0.0),
            mu: MU,
        };
        assert_eq!(collect_lattice(&l).len(), 54);
        assert_eq!(l.total(), 54);
    }

    #[test]
    fn reduces_to_walker_delta_when_circular() {
        // The key cross-check tying the new generator to the verified Walker: a circular lattice
        // (e = 0, ω = 0) with (No, Nso, Nc) = (P, S, F) is a Walker-Delta i: T/P/F, satellite for
        // satellite (M ≡ ν, slot-major = plane-major).
        let (planes, per_plane, phasing) = (4u32, 6u32, 3u32);
        let a = RE + 20_000e3;
        let inc = Angle::from_radians(56.0_f64.to_radians());

        let lattice = LatticeFlower {
            orbits: planes,
            sats_per_orbit: per_plane,
            config: phasing,
            semi_major_axis: a,
            eccentricity: 0.0,
            inclination: inc,
            arg_periapsis: Angle::from_radians(0.0),
            raan0: Angle::from_radians(0.0),
            mu: MU,
        };
        let walker = Walker {
            pattern: WalkerPattern::Delta,
            inclination: inc,
            planes,
            per_plane,
            phasing,
            semi_major_axis: a,
            mu: MU,
        };

        let l = collect_lattice(&lattice);
        let mut w = Vec::new();
        walker.generate(|e| w.push(e));
        assert_eq!(l.len(), w.len());
        for (a, b) in l.iter().zip(&w) {
            // RAAN identical; true anomaly identical mod 2π (both circular, so M ≡ ν).
            assert!((a.raan.radians() - b.raan.radians()).abs() < 1e-12);
            let dnu = (a.true_anomaly.radians() - b.true_anomaly.radians()).rem_euclid(TAU);
            let dnu = dnu.min(TAU - dnu);
            assert!(dnu < 1e-9, "nu mismatch {dnu:.2e}");
        }
    }

    #[test]
    fn lattice_steps_are_exact() {
        let (no, nso, nc) = (5u32, 4u32, 3u32);
        let l = LatticeFlower {
            orbits: no,
            sats_per_orbit: nso,
            config: nc,
            semi_major_axis: RE + 800e3,
            eccentricity: 0.0, // circular ⟹ M ≡ ν, so true anomaly reads back the lattice
            inclination: Angle::from_radians(1.2),
            arg_periapsis: Angle::from_radians(0.0),
            raan0: Angle::from_radians(0.0),
            mu: MU,
        };
        let s = collect_lattice(&l);
        // RAAN step between slots is 2π/No.
        let raan_step = s[usize::try_from(nso).unwrap()].raan.radians() - s[0].raan.radians();
        assert!((raan_step - TAU / f64::from(no)).abs() < 1e-12);
        // In-slot mean-anomaly step is 2π/Nso.
        let in_slot = s[1].true_anomaly.radians() - s[0].true_anomaly.radians();
        assert!((in_slot.rem_euclid(TAU) - TAU / f64::from(nso)).abs() < 1e-9);
        // Inter-slot along-track shift (first sat of slot 1 vs slot 0) is 2π·Nc/(No·Nso).
        let shift =
            s[usize::try_from(nso).unwrap()].true_anomaly.radians() - s[0].true_anomaly.radians();
        let expect = TAU * f64::from(nc) / (f64::from(no) * f64::from(nso));
        assert!(
            (shift.rem_euclid(TAU) - expect).abs() < 1e-9,
            "shift {shift:.4} vs {expect:.4}"
        );
    }

    #[test]
    fn elliptical_necklace_is_a_valid_distinct_constellation() {
        // e > 0 with Nso > 1 is a genuine necklace lattice — neither a plain Walker nor a single
        // Flower track. Confirm it builds valid orbits and is not all-circular.
        let l = LatticeFlower {
            orbits: 3,
            sats_per_orbit: 4,
            config: 1,
            semi_major_axis: RE + 20_200e3,
            eccentricity: 0.3,
            inclination: Angle::from_radians(63.434_f64.to_radians()),
            arg_periapsis: Angle::from_radians(270.0_f64.to_radians()),
            raan0: Angle::from_radians(0.0),
            mu: MU,
        };
        let sats = collect_lattice(&l);
        assert_eq!(sats.len(), 12);
        for s in &sats {
            assert_eq!(s.eccentricity, 0.3);
            assert!(
                s.semi_major_axis * (1.0 - s.eccentricity) > RE,
                "perigee below ground"
            );
        }
        // The 12 satellites occupy 3 distinct RAAN slots.
        let mut raans: Vec<f64> = sats.iter().map(|s| s.raan.radians()).collect();
        raans.sort_by(f64::total_cmp);
        raans.dedup_by(|a, b| (*a - *b).abs() < 1e-9);
        assert_eq!(raans.len(), 3);
    }

    /// (G2) The emitted satellites solve the Hermite-normal-form system that defines the lattice.
    ///
    /// Avendaño, Davis & Mortari (2013) define a 2-D lattice as the solutions of
    /// `[No 0; Nc' Nso]·[ΔΩ; ΔM] = 2π·[i; j]` (restated in Casanova, Avendaño & Mortari, IEEE
    /// Trans. AES 50(2), 2014, p. 1348, eq. 4). This module's `Nc` is `Nc' = −Nc mod No`
    /// (`derivations/lattice_flower.mac`); `derivations/lattice_flower.g` shows for every
    /// `No, Nso ≤ 8` that the module's points are exactly that system's `No·Nso` solutions. Read
    /// back from the emitted elements — `M` through the elements' own mean anomaly, so the
    /// eccentric cases also cross the Kepler solve — both rows must be whole turns. Bound: 1e-13
    /// turn per row, the round-off of an angle of a few radians times a coefficient below 10, plus
    /// the Kepler round trip at `e ≤ 0.3`.
    #[test]
    fn the_emitted_satellites_solve_the_hermite_normal_form_system() {
        for (no, nso, nc, e) in [
            (5_u32, 4_u32, 3_u32, 0.0),
            (6, 9, 2, 0.0),
            (4, 6, 7, 0.0),
            (3, 4, 1, 0.3),
            (7, 3, 0, 0.1),
        ] {
            let l = LatticeFlower {
                orbits: no,
                sats_per_orbit: nso,
                config: nc,
                semi_major_axis: RE + 20_000e3,
                eccentricity: e,
                inclination: Angle::from_radians(1.1),
                arg_periapsis: Angle::from_radians(0.4),
                raan0: Angle::from_radians(0.25),
                mu: MU,
            };
            let paper_nc = f64::from((no - nc % no) % no);
            let sats = collect_lattice(&l);
            assert_eq!(sats.len() as u32, no * nso);
            let m0 = sats[0].mean_anomaly().radians();
            let mut points = Vec::new();
            for s in &sats {
                let d_raan = (s.raan.radians() - 0.25) / TAU;
                let d_mean = (s.mean_anomaly().radians() - m0) / TAU;
                let rows = [
                    f64::from(no) * d_raan,
                    paper_nc * d_raan + f64::from(nso) * d_mean,
                ];
                for (k, row) in rows.iter().enumerate() {
                    let off = (row - libm::round(*row)).abs();
                    assert!(
                        off < 1e-13,
                        "{l:?}: row {k} is {off:.2e} turn off a whole number"
                    );
                }
                let t = f64::from(no * nso);
                points.push((
                    libm::round(d_raan * t) as i64,
                    libm::round(d_mean * t).rem_euclid(t) as i64,
                ));
            }
            points.sort_unstable();
            points.dedup();
            assert_eq!(
                points.len() as u32,
                no * nso,
                "{l:?}: coincident satellites"
            );
        }
    }
}
